import{z as o,x as s,o as e,c as i,q as A,j as t,D as a,d as n,s as B,S as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"生产案例与失败模式","description":"","frontmatter":{"title":"生产案例与失败模式","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-production-cases.md","filePath":"llm/agent-production-cases.md","lastUpdated":1791413859000}'),d={name:"llm/agent-production-cases.md"};function m(g,E,h,C,p,D){const r=s("Mermaid");return e(),i("div",null,[E[2]||(E[2]=A('<h1 id="生产案例与失败模式" tabindex="-1">生产案例与失败模式 <a class="header-anchor" href="#生产案例与失败模式" aria-label="Permalink to &quot;生产案例与失败模式&quot;">​</a></h1><div class="epigraph"><p>编码代理先成熟，不是模型偏爱代码，是代码域先凑齐了三件套——验证器便宜、环境可钉、副作用可逆；其他域照此补课。</p><footer>—— 据各代理产品的公开工程复盘与长视野评测报告整理</footer></div><p><a href="/llm/agent-regression-rollback">上一课</a>给变更立了守门；本课把镜头转向已经跑起来的真实系统，用案例与失败模式给全课程对账。案例带按域排：代理编码、计算机与浏览器代理、长视野任务——三个域的分数落差本身就是最大的发现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一个模型在不同域的表现差距巨大，差距的来源不是智力而是环境结构。代理编码（<a href="/llm/agentic-coding">Cursor 类代理编码</a>、<a href="/llm/claude-code-cli">Claude Code</a>、<a href="/llm/swe-agent">SWE-agent</a>、<a href="/llm/openhands">OpenHands / OpenDevin</a>、<a href="/llm/aider">Aider 工作流</a>）分数最高：测试是现成的验证器，仓库可装进容器钉住，git 让补丁可逆。<span class="marginnote">验证器就是能自动回答「做对了没」的程序：单元测试跑一遍红或绿，不用人看。编码域占便宜的核心是验证器别人早写好了（测试套件），代理每改一版都能立刻自检；而 GUI 操作「点对没点对」往往没有现成程序能判，只能靠像素猜或人审。</span><a href="/llm/computer-use">Computer Use / GUI 代理</a>与浏览器代理（<a href="/llm/browser-use-agent">Browser-use Agent</a>、<a href="/llm/openai-operator">OpenAI Operator</a>）分数塌一层：观察通道是像素与 DOM，环境不可钉、动作半不可逆。长视野任务再塌一层：<a href="/llm/vending-bench-2">Vending-Bench 2</a> 的年末余额显示，失败常常不是单步能力，而是数千万 token 时间轴上的遗忘与空转。跨域的失败不是随机的，可以编目——编目是本课的方法：每条失败回指一条机制，机制课给药。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>失败模式八条，每条带出处与解法。<strong>过早声称完成</strong>：任务没做完就宣布成功——解法是验证器门禁（<a href="/llm/agent-eval-success-process">评测：任务成功率与过程</a>的结果复核）。<strong>目标漂移</strong>：长任务中途换了目标而不自知——解法是目标与未决状态外置（<a href="/llm/agent-memory-implementation">记忆系统的实现</a>），周期性重述（<a href="/llm/agent-context-strategies">上下文管理策略</a>）。<strong>循环与空转</strong>：同一调用反复、原地打转——解法是熔断与检查点（<a href="/llm/agent-error-recovery">错误恢复与重试</a>）。<span class="marginnote">熔断借自电路保险丝：连续 N 次重试还失败就「跳闸」，停下来升级给人或换策略，而不是无限烧钱。没有熔断的循环最典型的账单事故是：同一个报错工具调用一晚上跑了几千遍。</span><strong>上下文腐烂遗忘</strong>：早期约束在长轨迹中部失效——解法是压缩加重述，不是加大窗口。<strong>注入劫持</strong>：读了不可信内容后动作被改写——解法是四层围栏（<a href="/llm/agent-guardrails">安全围栏</a>）。<strong>权限过宽</strong>：一次性授权全部工具，损失上限失控——解法是最小权限与任务级授权。<strong>成本失控</strong>：自由循环烧穿预算——解法是预算与三分结束语义（<a href="/llm/agent-loop-design-space">Agent 循环的设计空间</a>）。<strong>回归盲区</strong>：改了提示以为没事，长尾翻车——解法是版本账本与影子比对（<a href="/llm/agent-regression-rollback">回归测试与版本回滚</a>）。</p>',7)),(e(),t(l,null,{default:a(()=>[B(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOM%5B%22%E5%9F%9F%E9%80%89%E6%8B%A9%22%5D%20--%3E%20CODE%5B%22%E7%BC%96%E7%A0%81%EF%BC%9A%E9%AA%8C%E8%AF%81%E5%99%A8%20%2B%20%E5%8F%AF%E9%92%89%E7%8E%AF%E5%A2%83%20%2B%20%E5%8F%AF%E9%80%86%E5%89%AF%E4%BD%9C%E7%94%A8%22%5D%0A%20%20DOM%20--%3E%20GUI%5B%22GUI%EF%BC%9A%E5%83%8F%E7%B4%A0%E8%A7%82%E5%AF%9F%20%2B%20%E5%8D%8A%E4%B8%8D%E5%8F%AF%E9%80%86%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20DOM%20--%3E%20LONG%5B%22%E9%95%BF%E8%A7%86%E9%87%8E%EF%BC%9A%E9%81%97%E5%BF%98%20%2B%20%E7%A9%BA%E8%BD%AC%E4%B8%BB%E5%AF%BC%22%5D%0A%20%20CODE%20--%3E%20P1%5B%22%E5%A4%B1%E8%B4%A5%E9%9B%86%E4%B8%AD%E5%9C%A8%E8%BF%87%E7%A8%8B%E8%B4%A8%E9%87%8F%22%5D%0A%20%20GUI%20--%3E%20P2%5B%22%E5%A4%B1%E8%B4%A5%E9%9B%86%E4%B8%AD%E5%9C%A8%E8%A7%82%E5%AF%9F%E4%B8%8E%E5%9B%B4%E6%A0%8F%22%5D%0A%20%20LONG%20--%3E%20P3%5B%22%E5%A4%B1%E8%B4%A5%E9%9B%86%E4%B8%AD%E5%9C%A8%E8%AE%B0%E5%BF%86%E4%B8%8E%E9%A2%84%E7%AE%97%22%5D%0A%20%20P1%20--%3E%20FIX%5B%22%E6%8C%89%E5%A4%B1%E8%B4%A5%E7%BC%96%E7%9B%AE%E5%9B%9E%E6%8C%87%E6%9C%BA%E5%88%B6%E8%AF%BE%22%5D%0A%20%20P2%20--%3E%20FIX%0A%20%20P3%20--%3E%20FIX%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>编码域先成熟的机制值得展开：它不是模型能力曲线的问题，是<strong>验证器经济学</strong>的问题。测试套件让「语义失败」（<a href="/llm/agent-error-recovery">错误恢复与重试</a>）从不可见变成廉价可检测；容器让环境版本可钉，评测与回归才有了可重放的靶子；git 让副作用可逆，回滚（<a href="/llm/agent-regression-rollback">回归测试与版本回滚</a>）的窗口永远敞开。三件套凑齐后，<a href="/llm/agent-harness-design">Agent Harness 设计</a>的差异才直接反映到分数上——同一模型换工具面名次会掉，因为转移核变了。给其他域的启示按此倒推：上代理之前先找验证器；找不到验证器的域（开放网页、物理世界），先把观察通道与围栏补齐，再谈成功率。<a href="/llm/metr-time-horizon">METR Time Horizon</a> 的视界曲线是这些域差的统一刻度：任务越长，遗忘、漂移与预算三类失败的复合概率越高。</p>',2)),(e(),t(l,null,{default:a(()=>[B(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E7%BA%BF%E4%B8%8A%E6%95%85%E9%9A%9C%E7%9A%84%E4%B8%BB%E8%A6%81%E7%97%87%E7%8A%B6%3F%22%7D%20--%3E%7C%22%E5%AE%A3%E7%A7%B0%E5%AE%8C%E6%88%90%E4%BD%86%E6%B2%A1%E5%81%9A%E5%AE%8C%22%7C%20F1%5B%22%E8%BF%87%E6%97%A9%E5%A3%B0%E7%A7%B0%E5%AE%8C%E6%88%90%20%E2%86%92%20%E9%AA%8C%E8%AF%81%E5%99%A8%E9%97%A8%E7%A6%81%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%8C%E4%B8%80%E8%B0%83%E7%94%A8%E5%8F%8D%E5%A4%8D%E5%87%BA%E7%8E%B0%22%7C%20F2%5B%22%E5%BE%AA%E7%8E%AF%E7%A9%BA%E8%BD%AC%20%E2%86%92%20%E7%86%94%E6%96%AD%E4%B8%8E%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%AD%E9%80%94%E6%8D%A2%E4%BA%86%E7%9B%AE%E6%A0%87%22%7C%20F3%5B%22%E7%9B%AE%E6%A0%87%E6%BC%82%E7%A7%BB%20%E2%86%92%20%E7%8A%B6%E6%80%81%E5%A4%96%E7%BD%AE%E4%B8%8E%E9%87%8D%E8%BF%B0%22%5D%0A%20%20Q%20--%3E%7C%22%E6%97%A9%E6%9C%9F%E7%BA%A6%E6%9D%9F%E8%A2%AB%E5%BF%BD%E7%95%A5%22%7C%20F4%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E8%85%90%E7%83%82%20%E2%86%92%20%E5%8E%8B%E7%BC%A9%E5%8A%A0%E9%87%8D%E8%BF%B0%22%5D%0A%20%20Q%20--%3E%7C%22%E6%89%A7%E8%A1%8C%E4%BA%86%E4%B8%8D%E8%AF%A5%E5%81%9A%E7%9A%84%E5%8A%A8%E4%BD%9C%22%7C%20F5%5B%22%E6%B3%A8%E5%85%A5%E5%8A%AB%E6%8C%81%2F%E6%9D%83%E9%99%90%E8%BF%87%E5%AE%BD%20%E2%86%92%20%E5%9B%B4%E6%A0%8F%E4%B8%8E%E6%9C%80%E5%B0%8F%E6%9D%83%E9%99%90%22%5D%0A%20%20Q%20--%3E%7C%22%E8%B4%A6%E5%8D%95%E5%BC%82%E5%B8%B8%E5%A2%9E%E9%95%BF%22%7C%20F6%5B%22%E6%88%90%E6%9C%AC%E5%A4%B1%E6%8E%A7%20%E2%86%92%20%E9%A2%84%E7%AE%97%E4%B8%8E%E7%BB%93%E6%9D%9F%E8%AF%AD%E4%B9%89%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">早期通用框架（<a href="/llm/autogpt-arch">AutoGPT 架构笔记</a>）的教训浓缩成一句：目标放在提示里会漂，放在循环里会空转——把目标、状态与预算外置成系统对象，是第一代代理用烧掉的 API 账单换来的结论。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>案例的半衰期很短：产品形态、模型换代、基准修订都会让具体数字过期（SWE-bench 的分数逐年重写）；<span class="marginnote">半衰期借自物理：放射性物质的质量过一个周期衰减一半，这里指信息的参考价值随时间折损。两年前「某产品成功率 70%」今天可能毫无意义——模型换代了；但「目标要外置」这类挂在机制上的结论不会过期，这也是失败编目比案例数字长寿的原因。</span>失败模式编目比案例数字长寿，因为它挂在机制上。案例也不构成反事实证明：「编码代理成功」不推出「验证器是唯一因素」，模型在代码上的预训练密度同样在起作用。生产数字（接管率、成本、事故率）大多不公开，本课的口径以公开复盘与评测报告为限，不虚构内部数据。全课程的收束在下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>域的分数落差来自环境结构：验证器、可钉环境、可逆副作用三件套，编码域先凑齐。</li><li>失败八条编目：早声称完成、目标漂移、空转、腐烂遗忘、注入劫持、权限过宽、成本失控、回归盲区。</li><li>每条失败回指一条机制课；编目是排查法的索引，不是案例集。</li><li>上代理先找验证器；没有验证器的域先补观察通道与围栏。</li><li>案例数字半衰期短，机制编目长寿。</li><li>出处：据各代理产品公开复盘、Vending-Bench 与 METR 等评测报告整理。</li></ul>',5))])}const f=o(d,[["render",m]]);export{c as __pageData,f as default};
